const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let inputLines = [];
​
rl.on('line', line => {
    inputLines.push(line.trim());
    if (inputLines.length === 2) {
        let inputStr = inputLines[0];
        let k = parseInt(inputLines[1]);
        let n = inputStr.length;
​
        // 不满足最小长度，直接输出0
        if (n < 10 + k) {
            console.log(0);
            rl.close();
            return;
        }
​
        let res = 0;
        let digitCount = Array(10).fill(0);  // 记录数字出现次数
        let numberCount = 0;                  // 当前窗口数字种类数
        let countChar = 0;                    // 当前窗口字母数
        let left = 0;
​
        for (let right = 0; right < n; right++) {
            let c = inputStr[right];
            if (/[a-zA-Z]/.test(c)) {
                countChar++;                  // 字母计数+1
            }
            if (/\d/.test(c)) {
                let d = c.charCodeAt(0) - '0'.charCodeAt(0);
                digitCount[d]++;
                if (digitCount[d] === 1) {
                    numberCount++;            // 新增数字种类
                }
            }
​
            // 超过k个字母，移动左指针缩小窗口
            while (left <= right && countChar > k) {
                let leftChar = inputStr[left];
                if (/[a-zA-Z]/.test(leftChar)) {
                    countChar--;
                }
                if (/\d/.test(leftChar)) {
                    let d = leftChar.charCodeAt(0) - '0'.charCodeAt(0);
                    digitCount[d]--;
                    if (digitCount[d] === 0) {
                        numberCount--;         // 减少数字种类
                    }
                }
                left++;
            }
​
            // 当数字种类为10且字母数为k时，模拟移动左指针找更多合法子串
            if (numberCount === 10 && countChar === k) {
                let tmpLeft = left;
                let tempCount = digitCount.slice();
                let tmpNumberCount = numberCount;
                let tmpCountChar = countChar;
                while (tmpLeft <= right && tmpNumberCount === 10 && tmpCountChar === k) {
                    res++;
                    let ch = inputStr[tmpLeft];
                    if (/[a-zA-Z]/.test(ch)) {
                        tmpCountChar--;
                    }
                    if (/\d/.test(ch)) {
                        let d = ch.charCodeAt(0) - '0'.charCodeAt(0);
                        tempCount[d]--;
                        if (tempCount[d] === 0) {
                            tmpNumberCount--;
                        }
                    }
                    tmpLeft++;
                }
            }
        }
        console.log(res);
        rl.close();
    }
});
