package main
​
import (
    "fmt"
    "io"
    "os"
    "strconv"
    "strings"
    "unicode"
)
​
func main() {
    // 读取所有输入，兼容大数据量输入
    data, err := io.ReadAll(os.Stdin)
    if err != nil {
        panic(err)
    }
​
    // 按换行拆分输入，第一行为字符串，第二行为整数k
    lines := strings.Split(strings.TrimSpace(string(data)), "\n")
    if len(lines) < 2 {
        fmt.Println(0)
        return
    }
​
    input := strings.TrimSpace(lines[0])
    k, err := strconv.Atoi(strings.TrimSpace(lines[1]))
    if err != nil {
        fmt.Println(0)
        return
    }
​
    n := len(input)
    // 如果输入长度不足10个数字 + k个字符，直接返回0
    if n < 10+k {
        fmt.Println(0)
        return
    }
​
    res := 0                           // 结果计数
    digitCount := make([]int, 10)     // 记录数字0~9的出现次数
    numberCount := 0                  // 当前窗口中不同数字的个数
    countChar := 0                    // 当前窗口中字母的个数
    left := 0                         // 窗口左边界
​
    for right := 0; right < n; right++ {
        c := input[right]
​
        // 如果是字母，增加字符计数
        if unicode.IsLetter(rune(c)) {
            countChar++
        }
​
        // 如果是数字，增加对应数字的次数
        if c >= '0' && c <= '9' {
            d := c - '0'
            digitCount[d]++
            if digitCount[d] == 1 {
                numberCount++
            }
        }
​
        // 如果字母超过k个，移动左指针缩小窗口
        for left <= right && countChar > k {
            leftChar := input[left]
            if unicode.IsLetter(rune(leftChar)) {
                countChar--
            }
            if leftChar >= '0' && leftChar <= '9' {
                d := leftChar - '0'
                digitCount[d]--
                if digitCount[d] == 0 {
                    numberCount--
                }
            }
            left++
        }
​
        // 当前窗口合法：包含10种数字，字符数量为k
        if numberCount == 10 && countChar == k {
            // 模拟移动左边界，寻找所有可能的合法子串
            tmpLeft := left
            tmpDigitCount := make([]int, 10)
            copy(tmpDigitCount, digitCount)
            tmpNumberCount := numberCount
            tmpCountChar := countChar
​
            for tmpLeft <= right && tmpNumberCount == 10 && tmpCountChar == k {
                res++
                ch := input[tmpLeft]
                if unicode.IsLetter(rune(ch)) {
                    tmpCountChar--
                }
                if ch >= '0' && ch <= '9' {
                    d := ch - '0'
                    tmpDigitCount[d]--
                    if tmpDigitCount[d] == 0 {
                        tmpNumberCount--
                    }
                }
                tmpLeft++
            }
        }
    }
​
    // 输出合法子串数量
    fmt.Println(res)
}
